class Solution {
public:
    int countUnguarded(int m, int n, vector<vector<int>>& guards, vector<vector<int>>& walls) {
        vector<vector<int>> grid(m, vector<int>(n, 0)); // 0 empty, 1 guard, 2 wall, 3 guarded
        for (auto& g : guards) grid[g[0]][g[1]] = 1;
        for (auto& w : walls) grid[w[0]][w[1]] = 2;

        // Row sweep
        for (int r = 0; r < m; r++) {
            vector<pair<int,int>> obs; // (col, type)
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1 || grid[r][c] == 2) obs.push_back({c, grid[r][c]});
            }
            int k = (int)obs.size();
            for (int i = 0; i < k; i++) {
                if (obs[i].second != 1) continue; // not a guard
                int cc = obs[i].first;
                int rightLimit = (i + 1 < k) ? obs[i+1].first : n;
                for (int c = cc + 1; c < rightLimit; c++) {
                    if (grid[r][c] == 0) grid[r][c] = 3;
                }
                int leftLimit = (i - 1 >= 0) ? obs[i-1].first : -1;
                for (int c = cc - 1; c > leftLimit; c--) {
                    if (grid[r][c] == 0) grid[r][c] = 3;
                }
            }
        }

        // Column sweep
        for (int c = 0; c < n; c++) {
            vector<pair<int,int>> obs; // (row, type)
            for (int r = 0; r < m; r++) {
                if (grid[r][c] == 1 || grid[r][c] == 2) obs.push_back({r, grid[r][c]});
            }
            int k = (int)obs.size();
            for (int i = 0; i < k; i++) {
                if (obs[i].second != 1) continue;
                int rr = obs[i].first;
                int downLimit = (i + 1 < k) ? obs[i+1].first : m;
                for (int r = rr + 1; r < downLimit; r++) {
                    if (grid[r][c] == 0) grid[r][c] = 3;
                }
                int upLimit = (i - 1 >= 0) ? obs[i-1].first : -1;
                for (int r = rr - 1; r > upLimit; r--) {
                    if (grid[r][c] == 0) grid[r][c] = 3;
                }
            }
        }

        int ans = 0;
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (grid[r][c] == 0) ans++;
        return ans;
    }
};
